/* events.js — イベントの開催状態(開催中 / 開催前 / 終了)と並び順・絞り込み(T17、SPEC §8.2 §9)
 * 依存: window.KG_EVENTS(build.ps1 が data/events.json から生成し、このファイルの先頭に連結する。無くても DOM 属性で動く)
 * 「今日」は JST(UTC+9)で判定する。静的 HTML には全イベントを出し、読み込み時にここで状態を当てる(ビルド時刻で固定しない)。
 * markup(partials/event-card.html / event.html):
 *   [data-event="<id>"] data-start="YYYY-MM-DD" data-end="YYYY-MM-DD" data-dates="YYYY-MM-DD,…"(個別日。空なら期間)
 *     → data-status="ongoing|upcoming|ended" を付け、子の [data-event-status] にバッジ文言を入れる
 *   [data-event-list] … 直下の [data-event] を 開催中 → 開催前 → 終了 の順に並べ替える
 *     data-hide-ended … 終了を hidden にする / data-limit="N" … 表示を N 件に絞る
 *   #event-chips-course [data-course] / #event-chips-type [data-type] … 一覧の絞り込みチップ(AND)。?course=<id> で初期選択
 * 判定: dates があれば「今日が dates に含まれる=開催中」「今日より後の日がある=開催前」「それ以外=終了」。
 *       dates が無ければ startDate〜endDate の範囲(前=開催前、中=開催中、後=終了)。
 */
(function () {
  'use strict';

  var JST_OFFSET_MS = 9 * 60 * 60 * 1000;
  var LABELS = { ongoing: '開催中', upcoming: '開催前', ended: '終了' };
  var RANK = { ongoing: 0, upcoming: 1, ended: 2 };

  function str(v) { return (v === undefined || v === null) ? '' : String(v).trim(); }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function isKey(k) { return /^\d{4}-\d{2}-\d{2}$/.test(String(k)); }
  function todayKey() {
    var d = new Date(Date.now() + JST_OFFSET_MS);
    return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
  }

  // ---- データ(KG_EVENTS → id で引く。無ければ DOM 属性) ----
  var byId = {};
  (function () {
    var src = (window.KG_EVENTS && Array.isArray(window.KG_EVENTS.events)) ? window.KG_EVENTS.events : [];
    for (var i = 0; i < src.length; i++) {
      var e = src[i];
      if (e && str(e.id)) byId[str(e.id)] = e;
    }
  })();

  function eventOf(el) {
    var id = str(el.getAttribute('data-event'));
    var data = byId[id] || {};
    var dates = Array.isArray(data.dates) ? data.dates : str(el.getAttribute('data-dates')).split(',');
    return {
      id: id,
      start: str(data.startDate) || str(el.getAttribute('data-start')),
      end: str(data.endDate) || str(el.getAttribute('data-end')),
      dates: dates.map(str).filter(isKey).sort()
    };
  }

  // 開催状態。today は YYYY-MM-DD(文字列比較で前後が決まる)
  function statusOf(ev, today) {
    if (ev.dates.length) {
      if (ev.dates.indexOf(today) >= 0) return 'ongoing';
      for (var i = 0; i < ev.dates.length; i++) { if (ev.dates[i] > today) return 'upcoming'; }
      return 'ended';
    }
    if (isKey(ev.start) && today < ev.start) return 'upcoming';
    if (isKey(ev.end) && today > ev.end) return 'ended';
    if (isKey(ev.start) || isKey(ev.end)) return 'ongoing';
    return 'upcoming';
  }

  // 次に実施する日(個別日イベントの開催前・開催中に添える)
  function nextDate(ev, today) {
    for (var i = 0; i < ev.dates.length; i++) { if (ev.dates[i] >= today) return ev.dates[i]; }
    return '';
  }
  function fmtDate(key) {
    if (window.KG_CAL && typeof window.KG_CAL.fmtDate === 'function') { try { return window.KG_CAL.fmtDate(key); } catch (e) { /* fall through */ } }
    var p = key.split('-');
    return (+p[1]) + '/' + (+p[2]);
  }

  function applyStatus(el, today) {
    var ev = eventOf(el);
    var st = statusOf(ev, today);
    el.setAttribute('data-status', st);
    var badge = el.querySelector('[data-event-status]');
    if (badge) {
      var label = LABELS[st];
      if (st !== 'ended' && ev.dates.length) {
        var nd = nextDate(ev, today);
        if (nd) label += (nd === today ? '(本日)' : '(次は ' + fmtDate(nd) + ')');
      }
      badge.textContent = label;
      badge.className = 'event-status event-status--' + st;
      badge.hidden = false;
    }
    return { el: el, ev: ev, status: st };
  }

  function sortKey(item) {
    // 開催中: 終了が近い順 / 開催前: 開始が近い順 / 終了: 終了が新しい順
    if (item.status === 'ongoing') return item.ev.end;
    if (item.status === 'upcoming') return item.ev.start;
    return item.ev.end;
  }
  function compare(a, b) {
    var r = RANK[a.status] - RANK[b.status];
    if (r !== 0) return r;
    var ka = sortKey(a), kb = sortKey(b);
    if (a.status === 'ended') return ka < kb ? 1 : (ka > kb ? -1 : 0);
    return ka < kb ? -1 : (ka > kb ? 1 : 0);
  }

  function applyList(list, today) {
    var cards = Array.prototype.slice.call(list.querySelectorAll('[data-event]'));
    var items = cards.map(function (c) { return applyStatus(c, today); });
    items.sort(compare);
    var hideEnded = list.hasAttribute('data-hide-ended');
    var limit = parseInt(list.getAttribute('data-limit') || '0', 10);
    var shown = 0;
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      list.appendChild(it.el);   // 並び替え(appendChild で末尾へ移すだけ)
      var hide = (hideEnded && it.status === 'ended') || (limit > 0 && shown >= limit);
      it.el.hidden = hide;
      it.el.setAttribute('data-event-hidden', hide ? '1' : '0');   // 絞り込みと区別するため
      if (!hide) shown++;
    }
    return { items: items, shown: shown };
  }

  // ---- 一覧の絞り込みチップ(競馬場 × 種類の AND) ----
  function setupFilters(list) {
    var chipsCourse = document.getElementById('event-chips-course');
    var chipsType = document.getElementById('event-chips-type');
    if (!chipsCourse && !chipsType) return;
    var empty = document.getElementById('event-empty');
    var count = document.getElementById('event-count');
    var cards = Array.prototype.slice.call(list.querySelectorAll('[data-event]'));
    var sel = { course: '', type: '' };

    function render() {
      var shown = 0;
      cards.forEach(function (c) {
        var base = c.getAttribute('data-event-hidden') === '1';
        var on = !base &&
          (!sel.course || c.getAttribute('data-course') === sel.course) &&
          (!sel.type || c.getAttribute('data-type') === sel.type);
        c.hidden = !on;
        if (on) shown++;
      });
      if (empty) empty.hidden = shown > 0;
      if (count) count.textContent = shown + '件のイベント';
    }
    function bind(chips, attr, key) {
      if (!chips) return;
      chips.addEventListener('click', function (e) {
        var btn = e.target.closest('.chip');
        if (!btn || !chips.contains(btn)) return;
        chips.querySelectorAll('.chip').forEach(function (b) { b.classList.toggle('is-active', b === btn); });
        sel[key] = str(btn.getAttribute(attr));
        render();
      });
    }
    bind(chipsCourse, 'data-course', 'course');
    bind(chipsType, 'data-type', 'type');

    // ?course=<id> で競馬場チップを初期選択(競馬場ページの「すべて見る」から)
    var m = /[?&]course=([a-z0-9-]+)/.exec(window.location.search || '');
    if (m && chipsCourse) {
      var pre = chipsCourse.querySelector('.chip[data-course="' + m[1] + '"]');
      if (pre) {
        chipsCourse.querySelectorAll('.chip').forEach(function (b) { b.classList.toggle('is-active', b === pre); });
        sel.course = m[1];
      }
    }
    render();
  }

  function render() {
    var today = todayKey();
    var lists = document.querySelectorAll('[data-event-list]');
    var inList = {};
    for (var i = 0; i < lists.length; i++) {
      var r = applyList(lists[i], today);
      r.items.forEach(function (it) { inList[it.ev.id + '@' + i] = true; });
      if (lists[i].id === 'event-list') setupFilters(lists[i]);
    }
    // 一覧外(詳細ページの見出しなど)の単体要素
    var singles = document.querySelectorAll('[data-event]');
    for (var j = 0; j < singles.length; j++) {
      var el = singles[j];
      if (!el.closest('[data-event-list]')) applyStatus(el, today);
    }
  }

  window.KG_EV = { render: render, todayKey: todayKey, statusOf: function (id, today) {
    var e = byId[str(id)];
    if (!e) return '';
    var ev = { start: str(e.startDate), end: str(e.endDate), dates: (Array.isArray(e.dates) ? e.dates : []).map(str).filter(isKey).sort() };
    return statusOf(ev, today || todayKey());
  } };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', render);
  } else {
    render();
  }
})();
